CREATE TABLE IF NOT EXISTS `skill_nodes` (`slug` VARCHAR(24) PRIMARY KEY, `name` VARCHAR(64) NOT NULL, `icon` VARCHAR(64) NOT NULL DEFAULT 'fas fa-layer-group', `sort` INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT IGNORE INTO `skill_nodes` (`slug`, `name`, `icon`, `sort`) VALUES ('linux', 'Linux & Shell', 'fas fa-terminal', 1), ('git', 'Git', 'fas fa-code-branch', 2), ('sql', 'SQL & Data', 'fas fa-database', 3), ('php', 'PHP & OOP', 'fas fa-file-code', 4), ('laravel', 'Laravel', 'fa-brands fa-laravel', 5), ('docker', 'Docker', 'fa-brands fa-docker', 6), ('cicd', 'CI/CD', 'fas fa-infinity', 7), ('cloud', 'Cloud & AWS', 'fa-brands fa-aws', 8), ('networking', 'Networking', 'fas fa-network-wired', 9), ('security', 'Security & Observability', 'fas fa-shield-halved', 10);
CREATE TABLE IF NOT EXISTS `user_skill_mastery` (`user_id` INT NOT NULL, `node` VARCHAR(24) NOT NULL, `xp` INT NOT NULL DEFAULT 0, `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`user_id`, `node`), CONSTRAINT `fk_mastery_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE, CONSTRAINT `fk_mastery_node` FOREIGN KEY (`node`) REFERENCES `skill_nodes` (`slug`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `mastery_events` (`id` BIGINT AUTO_INCREMENT PRIMARY KEY, `user_id` INT NOT NULL, `node` VARCHAR(24) NOT NULL, `xp` INT NOT NULL, `source` VARCHAR(32) NOT NULL DEFAULT 'quest', `ref_type` VARCHAR(32) NULL, `ref_id` INT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `fk_mastery_events_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_mastery_events_user ON `mastery_events` (`user_id`, `created_at`);
